def total(n):
    if n == 0:
        return 0
    return n + total(n - 1)
print(total(4))

def power(b, e):
    if e == 0:
        return 1
    return b * power(b, e - 1)
p = power(2, 3)

def countdown(n):
    if n == 0:
        return "go"
